import { test, expect } from '@playwright/test';

test.describe('Modal Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.getByRole('button', { name: 'Open Modal' }).click(); // Adjust the button name as necessary
  });

  test('should close the modal when Escape key is pressed', async ({ page }) => {
    await expect(page.getByRole('dialog')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('dialog')).not.toBeVisible();
  });

  test('should remain open when clicking outside the modal', async ({ page }) => {
    await expect(page.getByRole('dialog')).toBeVisible();
    await page.click('body'); // Click outside the modal
    await expect(page.getByRole('dialog')).toBeVisible();
  });
});
